const legacyCharacters = new Set(['予','変','参','絡','準','確','遅','届','続','間','減','修']);
const seenCharacters = new Set        ();
const expandedKanji                                 = characterMeanings.flatMap(([character, meaning]) => {
  if (legacyCharacters.has(character) || seenCharacters.has(character)) return [];
  const words = expandedVocabulary.filter(word => word.word.includes(character));
  if (!words.length) return [];
  seenCharacters.add(character);
  return [{ id: `kx-${character.codePointAt(0) .toString(16)}`, character, meaning, wordIds: words.map(word => word.id), topicId: words[0].topicId }];
});

                                                                       
function question(id        , type                                 , word              , prompt        , choices          , rotation = 0)                  {
  if (choices.length !== 4 || new Set(choices.map(choice => choice.text.normalize('NFKC'))).size !== 4 || choices.filter(choice => choice.correct).length !== 1) throw new Error(`Invalid lexical choices: ${id}`);
  const rotated = [...choices.slice(rotation % 4), ...choices.slice(0, rotation % 4)];
  const options = rotated.map((choice, index) => ({ id: `${id}-${'abcd'[index]}`, text: choice.text }));
  return { id, skill: type === 'kanji-reading' ? 'kanji' : 'vocabulary', questionType: type, topicId: word.topicId, vocabularyId: word.id, prompt,
    options, correctOptionId: options[rotated.findIndex(choice => choice.correct)].id,
    explanations: Object.fromEntries(options.map((option, index) => [option.id, rotated[index].explanation])),
  };
}

// Distractors use reviewed words, not guessed alternative pronunciations. A
// different spelling with the same reading is excluded from orthography items.
function distractors(word              )                 {
  const ranked = expandedVocabulary.filter(candidate => candidate.word !== word.word && candidate.reading !== word.reading).map((candidate, index) => {
    const proximity = Math.abs(candidate.reading.length - word.reading.length)
      - (candidate.wordClass === word.wordClass ? 3 : 0)
      - (candidate.reading[0] === word.reading[0] ? 2 : 0)
      - (candidate.topicId === word.topicId ? 1 : 0);
    return { candidate, proximity, index };
  }).sort((a, b) => a.proximity - b.proximity || a.index - b.index);
  const result                 = [];
  for (const { candidate } of ranked) {
    if (!result.some(existing => existing.reading === candidate.reading || existing.word === candidate.word)) result.push(candidate);
    if (result.length === 3) break;
  }
  if (result.length !== 3) throw new Error(`Insufficient distractors for ${word.id}`);
  return result;
}

const readingQuestions = expandedVocabulary.filter(word => /\p{Script=Han}/u.test(word.word)).map((word, index) => question(
  `qx-reading-${word.id.slice(3)}`, 'kanji-reading', word,
  `「${word.word}」の読み方はどれですか。\n例文：${word.example}`,
  [{ text: word.reading, correct: true, explanation: `In this sentence, 「${word.word}」 is read ${word.reading}. It means “${word.meaning}.”` },
    ...distractors(word).map(other => ({ text: other.reading, explanation: `${other.reading} is the reading of 「${other.word}」 (${other.meaning}), not 「${word.word}」 in this sentence. The required reading is ${word.reading}.` }))], index % 4,
));

const orthographyQuestions = expandedVocabulary.filter((word, index) => index % 2 === 0 && /\p{Script=Han}/u.test(word.word) && word.example.includes(word.word)).map((word, index) => question(
  `qx-spelling-${word.id.slice(3)}`, 'orthography', word,
  `【　】の言葉の正しい表記はどれですか。\n${word.example.replace(word.word, `【${word.reading}】`)}`,
  [{ text: word.word, correct: true, explanation: `The spelling is 「${word.word}」, read ${word.reading}. It means “${word.meaning},” which fits this sentence.` },
    ...distractors(word).map(other => ({ text: other.word, explanation: `「${other.word}」 is read ${other.reading} and means “${other.meaning}.” It does not match the requested reading ${word.reading} in this sentence.` }))], (index + 1) % 4,
));

const lexicon = new Map(expandedVocabulary.map(word => [word.id, word]));
function authored(id        , type                                 , wordId        , prompt        , texts                               , correct         , reasons                               )                  {
  const word = lexicon.get(wordId);
  if (!word) throw new Error(`Missing lexical reference ${wordId}`);
  return question(id, type, word, prompt, texts.map((text, index) => ({ text, explanation: reasons[index], correct: index === correct })));
}

