function T(id        , lessonId        , passage        , answers          , reasons          ) {
  const lesson = lessons.find(g => g.id === `gx-${lessonId}`) ;
  const questionId = `qgx-text-${id}`;
  const rotation = questions.length % 4;
  const order = [0, 1, 2, 3].map(n => (n + rotation) % 4);
  const options = order.map((n, i) => ({ id: `${questionId}-o${i + 1}`, text: answers[n] }));
  questions.push({ id: questionId, skill: 'grammar', grammarId: lesson.id, topicId: lesson.topicId, questionType: 'text-grammar', prompt: `文章を読んで、（　）に入る最もよいものを一つ選んでください。\n\n${passage}`, options, correctOptionId: options[order.indexOf(0)].id, explanations: Object.fromEntries(order.map((n, i) => [options[i].id, reasons[n]])), evidence: passage.replace('（　）', answers[0]) });
  lesson.questionIds.push(questionId);
}
T('unexpected', 'noni-contrast', '昨日、旅行の持ち物を二回確認した。財布もかばんに入れたはずだった。しかし、駅でかばんを開けると財布がなかった。しっかり確認した（　）、忘れ物をしてしまった。', ['のに', 'ので', 'なら', 'について'], ['のに connects the actual careful checking with its unexpected failure to prevent a forgotten item.', 'ので would present the checking as the cause of forgetting; the passage instead states a contradiction.', 'なら makes checking a hypothetical condition, but the passage says it already happened.', 'について attaches to a topic noun; it cannot connect this verb clause to the unexpected result.']);
T('gratitude', 'okagede', '作文が苦手だったので、先生に相談した。先生は何度も説明してくれた。今は自分で分かりやすい文章を書ける。これは先生（　）だと思い、とても感謝している。', ['のおかげ', 'のせい', 'に対して', 'について'], ['のおかげ names the teacher’s help as the beneficial cause and matches explicit gratitude.', 'のせい normally blames a bad outcome; this passage explicitly appreciates beneficial help.', 'に対して marks a target, but would not form the causal noun predicate before だと思い.', 'について marks a topic, not the beneficial cause in this predicate.']);
T('unfavorable-cause', 'seide', '昨夜、映画を二本続けて見た。寝たのは午前三時だった。今朝は起きられず、仕事に遅れてしまった。遅くまで起きていた（　）、今日は体も重い。', ['せいで', 'おかげで', 'ついでに', 'ところで'], ['せいで attributes lateness and feeling unwell to staying up late, an unfavorable cause.', 'おかげで normally credits a beneficial cause; no appreciation or ironic framing appears here.', 'ついでに introduces an extra convenient action, not an unhealthy consequence.', 'ところで introduces a topic shift or another construction, not this direct unfavorable-cause link.']);
T('planned-expectation', 'hazu', '田中さんとは今日の三時に駅で会う約束をした。さっき「予定どおり行きます」というメールも来た。まだ姿は見えないが、もうすぐ来る（　）。私は改札の前で待つことにした。', ['はずだ', 'わけではない', 'べきではない', 'ところだった'], ['はずだ expresses an expectation supported by the appointment and confirming email.', 'わけではない denies the inference that he is coming, contrary to the evidence and decision to wait.', 'べきではない says he should not come, an obligation judgment unsupported by the appointment.', 'ところだった describes an earlier point just before an action; the passage is predicting his upcoming arrival.']);
T('qualified-denial', 'wakedehanai', '友達がケーキをすすめてくれたが、私は断った。「甘い物は嫌いなの？」と聞かれた。嫌いな（　）。昼ご飯を食べたばかりで、おなかがいっぱいだっただけだ。', ['わけではない', 'わけがないからだ', 'はずだったからだ', 'ついでだった'], ['わけではない denies the friend’s explanation: refusal does not mean dislike; being full is the actual reason.', 'わけがないからだ would claim impossibility of dislike as the cause of refusing, which does not explain the refusal.', 'はずだったからだ attributes refusal to a past expectation of dislike, contradicting the stated actual reason.', 'ついでだった refers to an incidental opportunity and does not deny the proposed dislike.']);
T('source', 'niyoruto', '図書館へ行く前に、市のホームページを見た。工事のため、明日は読書室が使えないと書いてあった。市のホームページ（　）、本の貸し出しはいつもどおり行うそうだ。', ['によると', 'にとって', 'として', 'に対して'], ['によると identifies the website as the source of the following report.', 'にとって introduces someone’s standpoint; the website is an information source, not the affected party.', 'として marks a role or capacity, not the source of reported information.', 'に対して marks a target or contrast, not the reporting source here.']);
T('personal-decision', 'kotonisuru', '最近、運動する時間が少なくなった。どうすればいいか考えた。会社までは歩いて二十分なので、自分で、明日から歩いて通う（　）。雨の日だけバスを使おうと思う。', ['ことにした', 'ことをした', 'ことがした', 'ことへした'], ['ことにした presents the writer’s own decision to walk to work after considering the problem.', 'This decision expression requires に; ことをした merely says did a thing and cannot form the intended construction.', 'が cannot replace に in ～ことにする.', 'へ marks direction and cannot replace に in this decision pattern.']);
T('recent-arrival', 'tabakari', 'この町に来たのは先週だ。駅への近道も、安い店もまだ知らない。引っ越した（　）なので、週末は近所を歩いてみようと思っている。', ['ばかり', 'ところに', 'ために', 'ながら'], ['ばかり presents the move a week ago as still recent, explaining unfamiliarity with the neighborhood.', 'ところに needs an event occurring at that stage; ところになので does not fit the sentence.', 'ために expresses a goal or cause connector; ためになので is malformed and does not present recency.', 'ながら does not attach to 引っ越した in this construction and does not express recent completion.']);
T('accessible-writing', 'youni-purpose', '地域のお祭りの案内を書くことになった。子どもも読むので、難しい漢字を使わず、大きな文字で書いた。誰でも内容が分かる（　）、短い文にした。', ['ように', 'のに', 'ついでに', 'ばかりに'], ['ように expresses the desired state: everyone can understand, supported by simple short sentences.', 'Concessive のに would say although everyone understands, which does not explain the intentional preparation; purpose のに does not fit this nonvolitional 分かる clause.', 'ついでに adds an incidental action; making the text accessible is the main stated goal.', 'ばかりに attributes an undesirable outcome to a cause, but the passage describes a beneficial intended result.']);
T('limited-amount', 'shika', '昼休みにお弁当を買おうとしたが、財布には三百円しか（　）。四百円のお弁当は買えないので、二百円のパンを買うことにした。', ['なかった', 'あった', 'あるだった', 'ないあった'], ['しか requires a negative predicate; なかった states the limited amount of three hundred yen and explains why four hundred yen was unaffordable.', 'あった is affirmative and cannot complete the restrictive しか construction.', 'あるだった is not a valid past form of ある.', 'ないあった combines incompatible forms instead of the past negative なかった.']);

