// These sources inform skill scope only; no exercises, passages, keys, recordings,
// chapter mappings or daily book assignments are reproduced.
                                 
                                                  
                                                    
const datasetAdvancedVocabulary               = [];
const datasetAdvancedGrammar            = [];
const datasetAdvancedReadings            = [];
const datasetAdvancedListening              = [];
const datasetAdvancedQuestions             = [];

function question(level               , slug        , skill                   , topicId         , questionType              , prompt        , choices             , links                   )         {
  const id = `ds-q-${level}-${slug}`;
  const shift = [...id].reduce((sum, c) => sum + c.charCodeAt(0), 0) % 4;
  const ordered = [...choices.slice(shift), ...choices.slice(0, shift)];
  const options = ordered.map(([text], i) => ({ id: `${id}-${'abcd'[i]}`, text }));
  datasetAdvancedQuestions.push({ id, skill, topicId, jlptLevel: level, questionType, prompt, options,
    correctOptionId: options[ordered.indexOf(choices[0])].id,
    explanations: Object.fromEntries(ordered.map((choice, i) => [options[i].id, choice[1]])), ...links });
  return id;
}

                                                                                                                                           
